void W906_TesterCommTick()
{
    W906_TimeDataHourTick();   // AI(W906-ELA-W48B) 20260928: ★W48-2 = B, golden HS_Function.cpp:233-238 (header)
    if (!g_inited)
        return;
    testercomm::TesterCommHub::Instance().PollHandler();
    W906_TcpPumpTick();  W906_CmdServerPumpTick();  W906_HanaRmsPumpTick();   /* AI(W906-ST02-C10) 20261002 (St02-E helper): golden 912 HANARMSClient events (POLLED socket), on this thread */   // P5: TCP/IP socket events + TimerTCPIPConnect / TimerProcessTCPData, on this thread as golden.  AI(W906-W10) 20260927 (St02-E): 7016 / 7017 accept / read / commands, on this (tick) thread.  AI(W906-W10fix) 20260928: was behind the P5 comment (dead)
    const DWORD now = ::GetTickCount();
    if (fTesterSide && now - g_lastConnect >= kConnectPeriodMs)
    {
        g_lastConnect = now;
        fTesterSide->ProcessHVisionConnect();   // golden Timer2Timer (main.cpp:21853): finds / wakes the bridge
        testercomm::TesterCommHub::Instance().PollHandler();
    }
    //AI(W906-GB-P2f) 20260926: golden Timer2Timer :22089-22234 (Handler -> bridge settings sync) runs on every Timer2
    //   tick after its InitialOK / SystemStart==false guards (:21495, :22080); change-driven, so cheap per tick.
    if (fTesterSide && InitialOK && !SystemStart)
        fTesterSide->SyncBridgeSettings();
    THandlerTesterSide::PublishSettings();   //AI(W906-GB-P6) 20260926: recipe / config changes reach the engine (HandlerSettings.h)
    //AI(W906-GB-P6) 20260926: 2A + Q2(a) -- the recipe's RS232 values changed (machine stopped): close the bridge; WakeupGPIB
    //   relaunches it and its LoadSetupData takes the new framing (golden CheckRs232StandardIni -> CloseGpibProgram).
    if (fTesterSide && W906_GpibAuxNeedsRestart(fTesterSide->bFind))
        fTesterSide->CloseGpibProgram("P6 2A: GPIB extra RS232 port follows the recipe");
}

bool TfRS232Main::LoadSetupData()
{
    TIniFile* IniFile=new TIniFile("D:\\RS232Standard\\System\\Setup.ini");

    CommTester->CommName = IniFile->ReadString( "COMPort", "CommName", "COM3");
    CommTester->BaudRate = IniFile->ReadInteger("COMPort", "BaudRate", 9600);
    CommTester->ByteSize = (TByteSize)IniFile->ReadInteger("COMPort" , "ByteSize", _7);
    CommTester->StopBits = (TStopBits)IniFile->ReadInteger("COMPort" , "StopBits", _1);
    CommTester->Parity   = (TParity  )IniFile->ReadInteger("COMPort" , "Parity"  , Even);
    CommTester->ReadIntervalTimeout =IniFile->ReadInteger("Detail Settng", "ReadIntervalTimeout", 70);    //wei 20150212  add
    //AI(W906-GB-P6) 20260926: user ruling 2A + Q2 = (a) (20260926) -- the framing follows the Handler recipe
    //  (TestIF_File.Rs232_Data, seeded once from this same Setup.ini by TesterComm/Handler/HandlerGpibAux.cpp), published
    //  in HandlerSettings.h before this bridge life started.  -1 (not a GPIB-mode recipe, extra port off, no Handler, or
    //  the recipe not seeded) keeps the golden Setup.ini values read above.  CommName and ReadIntervalTimeout stay golden.
#define W906_P6_GPIB_PORT_FROM_RECIPE 1   // 0 = golden (Setup.ini only)
#if W906_P6_GPIB_PORT_FROM_RECIPE
    {
        int baud=0, bs=0, sb=0, pa=0;
        g_auxFramingFromRecipe=testercomm::HsUnpackAuxFraming(testercomm::HsGpibAuxFraming().load(), &baud, &bs, &sb, &pa);
        if(g_auxFramingFromRecipe)
        {
            CommTester->BaudRate = baud;
            CommTester->ByteSize = (TByteSize)bs;
            CommTester->StopBits = (TStopBits)sb;
            CommTester->Parity   = (TParity  )pa;
        }
    }
#endif
    InitDataToMainForm();                                                       //Steven 20240615 : 修正RS232畫面顯示
#if W906_P6_GPIB_PORT_FROM_RECIPE
    //AI(W906-GB-P6) 20260926: the RS232 tab shows the recipe's framing; editing it here would only last until the next
    //  bridge start, so the four boxes are read-only while the recipe owns them (Update still saves CommName /
    //  ReadIntervalTimeout, and writes these values to Setup.ini as golden SetFormToData does).
    cbBaudRate->Enabled = !g_auxFramingFromRecipe;
    cbByteSize->Enabled = !g_auxFramingFromRecipe;
    cbStopBit->Enabled  = !g_auxFramingFromRecipe;
    cbParity->Enabled   = !g_auxFramingFromRecipe;
#endif
    delete IniFile;
    return true;
}

bool TfRS232Main::OpenTesterComm()                                              //JerryYang 20160630 RS232加入GPIB
{
    bool bRS232=false;                                                          //Jou 20240828 : 改成可以開關RS232功能
    if(CustomerCode==CC_HONPREC_QC          ||
       CustomerCode==CC_MAXIM_THAILAND      ||
       CustomerCode==CC_MAXIM               ||
       CustomerCode==CC_MAXIM_THAILAND      ||
       CustomerCode==CC_Microchip_Thai      ||
       CustomerCode==CC_Microchip_Phil      ||
       CustomerCode==CC_Microchip_China     ||
       CustomerCode==CC_SCC)
    {
        bRS232=CheckAndReadIniData("D:\\GPIB9045\\system\\general.ini", "OpenTesterComm", "RS232", true);
    }
    else
    {
        bRS232=CheckAndReadIniData("D:\\GPIB9045\\system\\general.ini", "OpenTesterComm", "RS232", false);
    }

    if(bRS232==false)
    {
        SerialPoll->tsRS232->TabVisible=false;                                  //Steven 20240615 : 修正RS232畫面顯示
        return false;
    }

    if(bCommConnect==true)
    {
        CloseTesterComm();
    }

    try
    {
        HANDLE handle=INVALID_HANDLE_VALUE;
        AnsiString CN="\\\\.\\"+CommTester->CommName;
        //AI(W906-GB-P1) 20260926: golden `CreateFile` (BCB6 ANSI build); spelled CreateFileA so a UNICODE build
        //  cannot turn it into CreateFileW.  Same open-and-close probe; its result is ignored, as in golden.
        handle=CreateFileA(CN.c_str(),
                          GENERIC_READ|GENERIC_WRITE,
                          0,
                          NULL,
                          OPEN_EXISTING,
                          FILE_ATTRIBUTE_NORMAL | FILE_FLAG_OVERLAPPED,
                          0);
        CloseHandle(handle);

        //AI(W906-GB-P1) 20260926: golden SPComm StartComm raises ECommsError("Error opening serial port") when the
        //  port cannot be opened (D:\HT9045\elec\Component\Spcomm.pas:379-388), which lands in the catch(...) below
        //  ("Connect : Fail", bCommConnect=false).  vclcompat TComm::StartComm never throws: it falls back to SIM
        //  (vclcompat/Comm.cpp:340-343).  That silent fallback is turned back into golden's exception here; a SIM
        //  the owner requested explicitly (SetSimMode(true) before this call) is left alone.
        const bool bSimRequested=CommTester->IsSimMode();
        CommTester->StartComm();
        if(CommTester->IsSimMode() && !bSimRequested)
        {
            CommTester->StopComm();
            throw std::runtime_error("Error opening serial port");
        }
        bCommConnect=true;

        ShowCommData("RS232 ==> Connect : OK", std::vector<Byte>(), true);
    }
    catch(...)
    {
        ShowCommData("RS232 ==> Connect : Fail", std::vector<Byte>(), true);
        bCommConnect = false;
        return false;
    }

    return true;
}

bool TfRS232Main::CloseTesterComm()                                             //JerryYang 20160630 RS232加入GPIB
{
    try
    {
        CommTester->StopComm();
        bCommConnect=false;

        ShowCommData("RS232 ==> Disconnect : OK", std::vector<Byte>(), true);
    }
    catch(...)
    {
        ShowCommData("RS232 ==> Disconnect : Fail", std::vector<Byte>(), true);
        return false;
    }

    return true;
}

void THandlerTesterSide::CloseGpibProgram(AnsiString Src)
{
//    if(TestIF.iTestType==RS232_MODE)                                          //wei 20150703 因為測試機不能關閉      //Isaac 20200903 :TTL RS232通訊，Mark
//        return ;

    if(bFind==false)
        return ;

    if(LastSet.iRunStartMode==rsmQAMode && bQAModeFinishCleanOut==true)         //Steven 20141023 : QA做完後的Bin
        return;

    COPYDATASTRUCT *pcp=new COPYDATASTRUCT ;
    pcp->dwData=0;
    HHandler2Gpib.bCloseGpib=true;
    if(CUSTOMER_CODE==CC_MTI || CUSTOMER_CODE==CC_PTI)                          //Sam 20190429 : Add CC_PTI_NEWWORK
        HHandler2Gpib.iLotStatus = 0;                                           //ChungHung OLP 聚成專用

    HHandler2Gpib.iSendCommand=MSG_CMD_CloseGpib;                               //wei 20150408 Add Close GPIB Command   MSG_CMD_NONE-->MSG_CMD_CloseGpib
    pcp->cbData=sizeof(HHandler2Gpib);
    pcp->lpData=(unsigned char *)&HHandler2Gpib.iSendCommand;
    SendToBridge(pcp);                                                          //AI(W906-GB-P2a) 20260926: rule 4, golden SendMessage(HVisionWnd,WM_COPYDATA,(WPARAM) NULL, (LPARAM)pcp);
    delete pcp;
    HHandler2Gpib.bCloseGpib=false;                                             //kevin 20150819 off-line 一直關GPIB
    MyDBIProcess("Process", "GPIB Close - "+Src);
    WakeupGPIBdelay.SetSecAndOn(5);
    bFind=false;
}

