void TComm::StartComm()
{
    if (pImpl_->bOpen)
        return;  // idempotent: already running

    pImpl_->simTx.clear();

#if defined(_WIN32)
    if (!pImpl_->bSimForced) {
        // Try a real port.  CommName is set by consumers as "\\.\COMx".
        const char* name = CommName.c_str();
        HANDLE h = INVALID_HANDLE_VALUE;  W906_CommJoinCloser(pImpl_->hCloser);   //AI(W906-COMM-STOPFAST) 20261006: the previous StopComm's close has finished before the exclusive re-open (same line)
        if (name != 0 && name[0] != '\0') {
            h = ::CreateFileA(name,
                              GENERIC_READ | GENERIC_WRITE,
                              0,           // no sharing (exclusive, as SPComm)
                              0,           // default security
                              OPEN_EXISTING,
                              0,           // synchronous I/O (blocking reader)
                              0);
        }
        if (h != INVALID_HANDLE_VALUE) {
            // Real port open.
            pImpl_->hFile = h;
            pImpl_->bSim  = false;
            pImpl_->bOpen = true;
            ApplyCommState_();

            // Launch the blocking reader thread (Win32 CreateThread).
            ::InterlockedExchange(&pImpl_->bStopReader, 0);  if (pImpl_->evStop != 0) ::ResetEvent(pImpl_->evStop);   //AI(W906-COMM-STOPFAST) 20261006: a restarted port idles again (same line)
            pImpl_->self = this;
            DWORD tid = 0;
            pImpl_->hReader = ::CreateThread(
                0, 0,
                reinterpret_cast<LPTHREAD_START_ROUTINE>(&TComm::ReaderProc_),
                pImpl_, 0, &tid);
            //AI(W906-TORQUE-COMM) 20260925: 寫入執行緒
            ::InterlockedExchange(&pImpl_->bStopWriter, 0);
            ::EnterCriticalSection(&pImpl_->csTx);
            pImpl_->txq.clear();
            ::LeaveCriticalSection(&pImpl_->csTx);
            pImpl_->evTx = ::CreateEventA(0, FALSE, FALSE, 0);
            pImpl_->hWriter = ::CreateThread(
                0, 0,
                reinterpret_cast<LPTHREAD_START_ROUTINE>(&TComm::WriterProc_),
                pImpl_, 0, &tid);
            return;
        }
    }
#endif

    // No hardware (or sim forced / non-Windows): succeed in sim mode.
    pImpl_->bSim  = true;
    pImpl_->bOpen = true;
}

void TComm::StopComm()
{
    if (!pImpl_->bOpen)
        return;

#if defined(_WIN32)
    if (!pImpl_->bSim) {
        // Signal the reader to exit.  The reader uses an interval-timeout
        // ReadFile (returns promptly with 0 bytes when idle), so it observes
        // the stop flag and returns; closing the handle also breaks any
        // in-flight ReadFile.  We avoid CancelIoEx (not available on the
        // MinGW.org default Win32 headers / pre-Vista target).
        //AI(W906-TORQUE-COMM) 20260925: 先讓寫入執行緒送完佇列再離開（每包 WriteFile 最多 2 s）
        ::InterlockedExchange(&pImpl_->bStopWriter, 1);
        if (pImpl_->hWriter != 0) {
            if (pImpl_->evTx != 0) ::SetEvent(pImpl_->evTx);
            ::WaitForSingleObject(pImpl_->hWriter, 5000);
            ::CloseHandle(pImpl_->hWriter);
            pImpl_->hWriter = 0;
        }
        if (pImpl_->evTx != 0) { ::CloseHandle(pImpl_->evTx); pImpl_->evTx = 0; }
        ::InterlockedExchange(&pImpl_->bStopReader, 1);  if (pImpl_->evStop != 0) ::SetEvent(pImpl_->evStop);   //AI(W906-COMM-STOPFAST) 20261006: wake the reader's idle wait now (same line)
        if (pImpl_->hReader != 0) {
            ::WaitForSingleObject(pImpl_->hReader, 2000);
            ::CloseHandle(pImpl_->hReader);
            pImpl_->hReader = 0;
        }
        if (pImpl_->hFile != INVALID_HANDLE_VALUE) {
            W906_CommJoinCloser(pImpl_->hCloser);  pImpl_->hCloser = ::CreateThread(0, 0, reinterpret_cast<LPTHREAD_START_ROUTINE>(&W906_CommCloserProc), (void*)pImpl_->hFile, 0, 0);  if (pImpl_->hCloser == 0) ::CloseHandle(pImpl_->hFile);   //AI(W906-COMM-STOPFAST) 20261006: the port's CloseHandle on a short-lived thread -- measured 11-12.7 ms per close on this machine's COM2 (driver), on the main loop every time golden resets the port after a temperature controller stops answering (bthermo case 2500 / 250 / 255 / 200 StopComm); StartComm / the dtor wait for it, so a re-open never races the close.  Was: ::CloseHandle(pImpl_->hFile);
            pImpl_->hFile = INVALID_HANDLE_VALUE;
        }
        pImpl_->self = 0;
    }
#endif

    pImpl_->bOpen = false;
    // Restore sim flag to the explicit request for the next StartComm.
    pImpl_->bSim = pImpl_->bSimForced;
}

void TComm::SetSimMode(bool bSim)
{
    pImpl_->bSimForced = bSim;
    if (!pImpl_->bOpen)
        pImpl_->bSim = bSim;   // takes effect at next StartComm
}

static unsigned long __stdcall W906_CommCloserProc(void* h)
{
#if defined(_WIN32)
    ::CloseHandle(static_cast<HANDLE>(h));
#else
    (void)h;
#endif
    return 0;
}

static void W906_CommJoinCloser(void*& hCloser)
{
#if defined(_WIN32)
    if (hCloser != 0) {
        ::WaitForSingleObject(static_cast<HANDLE>(hCloser), 5000);
        ::CloseHandle(static_cast<HANDLE>(hCloser));
        hCloser = 0;
    }
#else
    hCloser = 0;
#endif
}
